npm install @json-render/core @json-render/react-three-fiber @react-three/fiber @react-three/drei three Why json-render?json-render 是一个 生成式 UI 框架：AI 从自然语言提示生成界面，受限于你定义的组件。你设置护栏，AI 在其中生成： Guardrailed - AI can only use components in your catalog 受护栏约束的 - AI 只能使用您目录中的组件 可预测的 - JSON 输出每次都与你的 JSON 模式匹配 快速 - 流式传输并随着模型响应逐步渲染 跨平台 - React、Vue、Svelte、Solid（web）、React Native（mobile）来自同一个目录 一应俱全 - 36 个预构建的 shadcn/ui 组件，即开即用 Quick Start import { defineCatalog } from "@json-render/core";
import { schema } from "@json-render/react/schema";
import { z } from "zod"; const catalog = defineCatalog(schema, { components: { Card: { props: z.object({ title: z.string() }), description: "A card container", }, Metric: { props: z.object({ label: z.string(), value: z.string(), format: z.enum(["currency", "percent", "number"]).nullable(), }), description: "Display a metric value", }, Button: { props: z.object({ label: z.string(), action: z.string(), }), description: "Clickable button", }, }, actions: { export_report: { description: "Export dashboard to PDF" }, refresh_data: { description: "Refresh all metrics" }, },
});import { defineRegistry, Renderer } from "@json-render/react"; const { registry } = defineRegistry(catalog, { components: { Card: ({ props, children }) => ( <div className="card"> <h3>{props.title}</h3> {children} </div> ), Metric: ({ props }) => ( <div className="metric"> <span>{props.label}</span> <span>{format(props.value, props.format)}</span> </div> ), Button: ({ props, emit }) => ( <button onClick={() => emit("press")}>{props.label}</button> ), },
});function Dashboard({ spec }) { return <Renderer spec={spec} registry={registry} />;
} 就是这样。 AI 生成 JSON，你安全地渲染它。 Packages Package Description @json-render/core 模式、目录、AI 提示词、动态属性、SpecStream 工具 @json-render/react React 渲染器，上下文，钩子 @json-render/vue Vue 3 渲染器，组合式函数，提供器 @json-render/svelte Svelte 5 renderer with runes-based reactivity 基于 runes 的响应性的 Svelte 5 渲染器 @json-render/solid SolidJS 渲染器，具备细粒度响应式上下文 @json-render/shadcn 36 个预构建的 shadcn/ui 组件（Radix UI + Tailwind CSS） @json-render/react-three-fiber React Three Fiber 3D 场景渲染器（19 个内置组件） @json-render/react-native 带有标准移动组件的 React Native 渲染器 @json-render/remotion Remotion 视频渲染器，时间轴架构 @json-render/react-pdf React PDF 渲染器，用于从规范生成 PDF 文档 @json-render/react-email React Email renderer for HTML/plain-text emails from specs React 电子邮件渲染器，用于根据规范生成 HTML/纯文本电子邮件 @json-render/ink Ink 终端渲染器，带有用于交互式文本用户界面的内置组件。 @json-render/image 用于 SVG/PNG 输出的图像渲染器（OG 图像、社交卡片）通过 Satori @json-render/codegen 从 json-render UI 树生成代码的工具 @json-render/redux Redux / Redux Toolkit 适配器 用于 StateStore @json-render/zustand Zustand adapter for StateStore @json-render/jotai Jotai adapter for StateStore @json-render/xstate XState 状态存储（原子）适配器 用于 StateStore @json-render/mcp MCP Apps integration for Claude, ChatGPT, Cursor, VS Code MCP Apps 与 Claude、ChatGPT、Cursor、VS Code 的集成 @json-render/yaml YAML 传输格式，带流式解析器、编辑模式、AI SDK 转换 Renderers React (UI) import { defineRegistry, Renderer } from "@json-render/react";
import { schema } from "@json-render/react/schema"; // Flat spec format (root key + elements map)
